sys_ux_client_script.script:
/**
 * Auto-advance the playbook card to the activity that just became live.
 *
 * Why an event and not the click: PLAYBOOK#ITEM_STARTED fires when an activity
 * moves to In Progress. In a NESTED playbook the engine activates the next
 * activity a moment AFTER the click that finished the previous one, so the
 * card's own post-click refresh ran while the next activity was still Pending -
 * there was nothing to select, and the card sat on the finished activity.
 * Standalone playbooks advance inside the same request, which is why they
 * looked fine. Reacting to ITEM_STARTED works for both.
 *
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    const p = (event && event.payload) || {};
    if (!p.activityContextId) {
        return;
    }
    api.setState('currentActivityContextId', p.activityContextId);
}
